{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle configuration to clean up incomplete multipart uploads, which can leave unnecessary objects and storage costs."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "No Public Access Block is associated with this bucket, so future ACL or bucket-policy changes could unintentionally expose its data publicly."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is not enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The bucket does not deliver server access logs, reducing visibility into requests made to potentially sensitive data."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is not enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The bucket has no replication configuration, leaving its data without the geographic redundancy required by the referenced policy."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 public ACLs are not blocked",
      "resource": "aws_s3_bucket.data",
      "severity": "CRITICAL",
      "explanation": "The bucket does not explicitly block public ACLs, allowing a future public ACL to expose the bucket or its objects."
    }
  ],
  "patched_code": "variable "s3_access_logging_target_bucket" {
  description = "Name of the secured S3 bucket that receives server access logs."
  type        = string
}

variable "s3_replication_destination_bucket_arn" {
  description = "ARN of the versioned S3 replication destination bucket in a different AWS region."
  type        = string
}

variable "s3_replication_role_arn" {
  description = "ARN of the IAM role used by S3 to replicate objects to the destination bucket."
  type        = string
}

resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket = aws_s3_bucket.data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "data" {
  bucket = aws_s3_bucket.data.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_logging" "data" {
  bucket        = aws_s3_bucket.data.id
  target_bucket = var.s3_access_logging_target_bucket
  target_prefix = "${local.resource_prefix.value}-data-access-logs/"
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_replication_configuration" "data" {
  depends_on = [aws_s3_bucket_versioning.data]

  bucket = aws_s3_bucket.data.id
  role   = var.s3_replication_role_arn

  rule {
    id     = "cross-region-replication"
    status = "Enabled"

    filter {}

    destination {
      bucket        = var.s3_replication_destination_bucket_arn
      storage_class = "STANDARD"
    }
  }
}
",
  "fix_summary": "Added a complete S3 Public Access Block, lifecycle cleanup, server access logging, versioning, and replication configuration. Required target bucket and replication role/destination values are supplied through variables so no credentials, secrets, or fabricated external resources are embedded."
}
